class Solution:
    def smallestStableIndex(self, nums, k):
        n = len(nums)
        sufMin = [0]*n
        m = float('inf')
        for i in range(n-1, -1, -1):
            m = min(m, nums[i])
            sufMin[i] = m
        pm = float('-inf')
        for i in range(n):
            pm = max(pm, nums[i])
            if pm - sufMin[i] <= k:
                return i
        return -1

