class Solution {
    public int smallestStableIndex(int[] nums, int k) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            long pm = Long.MIN_VALUE, sm = Long.MAX_VALUE;
            for (int j = 0; j <= i; j++) pm = Math.max(pm, nums[j]);
            for (int j = i; j < n; j++) sm = Math.min(sm, nums[j]);
            if (pm - sm <= (long) k) return i;
        }
        return -1;
    }
}

